Bash(# 检查 settings.json 中是否有 ECC 的环境变量 hooks（之前出问题的）
cat ~/.claude/settings.json 2>/dev/null | python -c "
import json, sys
data = json.load\(sys.stdin\)
hooks = data.get\('hooks', {}\)

# 找所有使用 CLAUDE_PLUGIN_ROOT 的 hooks
print\('=== 使用 CLAUDE_PLUGIN_ROOT 的 Hooks ==='\)
for event, hook_list in hooks.items\(\):
    for i, hg in enumerate\(hook_list\):
        for h in hg.get\('hooks', []\):
            cmd = h.get\('command', ''\)
            if 'CLAUDE_PLUGIN_ROOT' in cmd:
                print\(f'  [{event}] #{i+1}: {cmd[:100]}...'\)

print\(\)
print\('=== 使用硬编码路径的 Hooks ==='\)
for event, hook_list in hooks.items\(\):
    for i, hg in enumerate\(hook_list\):
        for h in hg.get\('hooks', []\):
            cmd = h.get\('command', ''\)
            if 'everything-claude-code' in cmd and 'CLAUDE_PLUGIN_ROOT' not in cmd:
                print\(f'  [{event}] #{i+1}: {cmd[:100]}...'\)

print\(\)
print\('=== 功能重叠分析 ==='\)
print\('ECC Stop hooks:'\)
for hg in hooks.get\('Stop', []\):
    for h in hg.get\('hooks', []\):
        print\(f'  - {h.get\(\\"command\\", \\"\\"\)[:80]}'\)
print\('OMC Stop hooks: persistent-mode \(ultrawork/ralph/autopilot/todo-continuation\)'\)
print\(\)
print\('ECC SessionStart hooks:'\)
for hg in hooks.get\('SessionStart', []\):
    for h in hg.get\('hooks', []\):
        print\(f'  - {h.get\(\\"command\\", \\"\\"\)[:80]}'\)
print\('OMC SessionStart hooks: rules-injector, mode-registry, setup'\)
" 2>/dev/null)
